package dev.infiniterra.api;

import dev.infiniterra.impl.guess.GuessTint;
import dev.infiniterra.impl.guess.GuessWorld;
import dev.infiniterra.impl.guess.VoxyGuess;
import net.minecraft.client.renderer.state.level.CameraRenderState;
import org.jspecify.annotations.Nullable;

import java.util.OptionalLong;

/**
 * Terrain guessed from the world seed where no real chunks have been seen: generated by a private
 * worldgen server and shown through the LOD mod (Voxy), with a fading blue tint so guesses are never
 * mistaken for the real world. Real chunks and the LOD already known always win over guesses.
 * <p>
 * The host decides which world and seed, and when the guess is shown; it calls {@link #update} every tick.
 * Whether the seed fits the world shows in {@link SeedCheck}.
 */
public final class TerrainGuess {
	private TerrainGuess() {
	}

	public enum State {STARTING, READY, FAILED}

	/** The guess for the current world, dimension and seed. */
	public interface Status {
		State state();

		/** Why it failed, or null. */
		@Nullable String error();

		/** Chunks generated, chunks known real, chunks waiting to be generated. */
		int guessedCount();

		int realCount();

		int pending();

		/** The LOD already known being copied in: columns done and in all (0 when nothing to copy). */
		int imported();

		int importTotal();

		/** Chunks copied from the LOD and failed to generate this session (tests and debugging). */
		int copiedThisSession();

		int failedCount();

		boolean isGuessed(int chunkX, int chunkZ);

		boolean isReal(int chunkX, int chunkZ);

		/** Has the LOD mod rebuild the guessed terrain's view from what is stored (fixes leftover holes). */
		void reloadView();
	}

	/** Whether guessed terrain can be shown at all (needs Voxy). */
	public static boolean supported() {
		return GuessWorld.supported();
	}

	/**
	 * Every tick: the world ({@code worldKey}, e.g. a server address or a save folder; null outside a
	 * world) and its seed (empty: none known, no guess), whether the guess is shown now, and the point it is
	 * generated around while shown.
	 */
	public static void update(@Nullable String worldKey, OptionalLong seed, boolean show, double focusX, double focusZ) {
		dev.infiniterra.impl.guess.SeedCheckImpl.update(worldKey, seed);
		dev.infiniterra.impl.guess.WorldMirror.update(worldKey, seed);
		if (dev.infiniterra.impl.dh.DhProbe.present()) dev.infiniterra.impl.dh.DhHost.update(worldKey, seed);
		GuessWorld.reconcile(worldKey, seed);
		GuessWorld world = GuessWorld.current();
		boolean shown = show && world != null && world.state() == GuessWorld.State.READY;
		if (shown) world.tick(focusX, focusZ);
		VoxyGuess.show(shown);
	}

	/** The current guess, or null (no seed, no world, not supported). */
	public static @Nullable Status current() {
		GuessWorld w = GuessWorld.current();
		return w == null ? null : w.status();
	}

	/** Starts over after a failed start. */
	public static void retry() {
		GuessWorld.retry();
	}

	/** Radius around the focus point that is generated (chunks). */
	public static int radius() {
		return GuessWorld.radius;
	}

	public static void setRadius(int chunks) {
		GuessWorld.radius = chunks;
	}

	/** Whether the LOD mod shows the guessed terrain now. */
	public static boolean showing() {
		return VoxyGuess.showing();
	}

	/** The tint: strongest opacity (it fades down to a quarter and back) and seconds per fade cycle. */
	public static void setTint(float strength, float cycleSeconds) {
		GuessTint.strength = strength;
		GuessTint.cycleSeconds = cycleSeconds;
	}

	/** Draws the tint over the guessed chunks of the frame just rendered (after the level, while {@link #showing()}). */
	public static void drawTint(CameraRenderState camera) {
		GuessWorld w = GuessWorld.current();
		if (w != null && VoxyGuess.showing()) GuessTint.render(camera, w);
	}

	/** Tint draws so far (tests). */
	public static long tintDrawn() {
		return GuessTint.drawn;
	}
}
